function toggleMenu(){document.getElementById("nav-menu").classList.toggle("active"),document.querySelector(".overlay").classList.toggle("active")}function calcularTMB(){const e=document.querySelector('input[name="sexo"]:checked').value,t=window.converterParaNumero(document.getElementById("idade").value),a=window.converterParaNumero(document.getElementById("peso").value),n=window.converterParaNumero(document.getElementById("altura").value),o=window.converterParaNumero(document.getElementById("atividade").value),l=document.getElementById("resultado-area");if(isNaN(t)||isNaN(a)||isNaN(n)||t<=0||a<=0||n<=0)return void alert("Por favor, preencha idade, peso e altura corretamente.");let d=0;d="masculino"===e?10*a+6.25*n-5*t+5:10*a+6.25*n-5*t-161;const r=d*o,c=r-500,u=r,m=r+500;l.style.display="block",document.getElementById("valor-tmb").textContent=Math.round(d)+" kcal",document.getElementById("cal-perder").textContent=Math.round(c)+" kcal",document.getElementById("cal-manter").textContent=Math.round(u)+" kcal",document.getElementById("cal-ganhar").textContent=Math.round(m)+" kcal",window.innerWidth<600&&l.scrollIntoView({behavior:"smooth",block:"start"}),"function"==typeof window.salvarCalculo&&window.salvarCalculo("Calculadora de TMB",`Idade: ${t} | Peso: ${a}kg | Atividade: ${o}`,`TMB: ${Math.round(d)} kcal | Manter: ${Math.round(u)} kcal`)}